const executionId=String($execution?.id??"manual");
const definitions=[
 {testId:"A01",name:"Graduate count numeric integrity",kind:"numeric_count",chatInput:"فقط عدد: تعداد کل فارغ‌التحصیلان دانشگاه چند نفر است؟",expectedCount:30},
 {testId:"A05",name:"Scalar graduate count and employment average",kind:"scalar_aggregate",chatInput:"تعداد فارغ التحصیلان و میانگین مدت اشتغال را محاسبه کن",expectedCount:30,expectedAverage:6.93},
 {testId:"A02",name:"Course C002 retrieval",kind:"course_lookup",chatInput:"نام درس با شناسه C002 چیست؟",expectedCourseId:"C002",expectedCourseName:"ساختمان داده"},
 {testId:"A03",name:"Independent multi-plan analysis",kind:"multi_plan",chatInput:"تعداد کل فارغ‌التحصیلان دانشگاه را گزارش کن و به‌صورت مستقل پنج مهارت با بیشترین شکاف مهارتی بازار را نیز رتبه‌بندی کن.",expectedCount:30},
 {testId:"A04",name:"Out-of-domain rejection",kind:"out_of_scope",chatInput:"قیمت روز بیت‌کوین چقدر است؟"}

 {testId:"A06",name:"University-market skill demand analysis",kind:"skill_demand",chatInput:"تحلیل تقاضای مهارت‌های بازار کار را ارائه کن."},
 {testId:"A07",name:"Top skill-gap ranking",kind:"skill_gaps",chatInput:"پنج مهارت با بیشترین شکاف مهارتی بازار را رتبه‌بندی کن."},
 {testId:"A08",name:"Course-level skill-gap ranking",kind:"course_gap",chatInput:"بیشترین شکاف مهارتی در کدام درس‌ها مشاهده می‌شود؟",expectedCourseId:"C013",expectedCourseName:"رایانش ابری"},
 {testId:"A09",name:"English course lookup and response language",kind:"english_course_lookup",chatInput:"What is the name of course C002?",expectedCourseId:"C002",expectedCourseName:"Data Structures"},
 {testId:"A10",name:"Nested AND/OR graduate filter",kind:"nested_filter",chatInput:"تعداد فارغ‌التحصیلانی را محاسبه کن که حوزه شغلی آن‌ها AI یا Data است و ارتباط شغل با رشته حداقل 4.5 است."},
 {testId:"A11",name:"Grouped multi-metric graduate analytics",kind:"multi_metric",chatInput:"برای هر حوزه شغلی، تعداد فارغ‌التحصیلان و میانگین مدت اشتغال را در یک جدول گزارش کن."},
 {testId:"A12",name:"Named market-skill details",kind:"skill_details",chatInput:"تقاضا و فراوانی مهارت‌های Python و SQL را مقایسه کن."},
 {testId:"A13",name:"University-market management report",kind:"management_report",chatInput:"یک گزارش مدیریتی از وضعیت دانشگاه و بازار کار همراه با پیشنهادهای اجرایی تهیه کن."}
]; 
return definitions.map(test=>{
 const sessionId="nexusops-e2e-"+executionId+"-"+test.testId;
 return {json:{...test,sessionId,requestBody:{action:"sendMessage",sessionId,chatInput:test.chatInput}}};
});

function parseBody(value){
 if(value&&typeof value==="object")return value;
 const source=String(value??"").trim();
 if(!source)return null;
 try{return JSON.parse(source)}catch{return {output:source}}
}
function normalizeDigits(value){
 return String(value??"").replace(/[۰-۹]/g,d=>"۰۱۲۳۴۵۶۷۸۹".indexOf(d)).replace(/[٠-٩]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d)).replace(/٫/g,".").replace(/٬/g,",");
}
function responseText(body){
 if(Array.isArray(body))body=body[0];
 if(typeof body==="string")return body;
 if(!body||typeof body!=="object")return String(body??"");
 for(const key of ["output","text","message"])if(typeof body[key]==="string")return body[key];
 if(body.data&&typeof body.data==="object")return responseText(body.data);
 return JSON.stringify(body);
}
const cases=$("Build Agent Test Cases").all().map(x=>x.json);
const items=$input.all();
const responsesAligned=items.length===cases.length;
const results=[];
for(let i=0;i<cases.length;i++){
 const test=cases[i],entry=responsesAligned?items[i]:null;
 const response=entry?.json??{},body=parseBody(response.body??response.data),text=responseText(body),normalized=normalizeDigits(text);
 const statusCode=Number(response.statusCode??0);
 let passed=false,detail="";
 if(!entry)detail="Response correlation failed: serial loop output count does not match the case count.";
 else if(response.error)detail="Transport error: "+String(response.error.message??response.error).slice(0,500);
 else if(statusCode&& (statusCode<200||statusCode>=300))detail="Chat Trigger returned HTTP "+statusCode+": "+text.slice(0,500);
 else if(!text.trim())detail="Chat Trigger returned an empty response.";
 else if(test.kind==="numeric_count"){
  passed=new RegExp("(?:^|\\D)"+test.expectedCount+"(?:\\D|$)").test(normalized);
  detail=passed?"Expected graduate count "+test.expectedCount+" appears in the actual Agent response.":"Expected exact count token "+test.expectedCount+" was not found: "+text.slice(0,700);
 }else if(test.kind==="scalar_aggregate"){
  const numericTokens=normalized.match(/-?\\d+(?:[.,]\\d+)?/g)??[];
  const hasCount=numericTokens.some(value=>Number(value.replace(",", "."))===Number(test.expectedCount));
  const hasAverage=numericTokens.some(value=>Number(value.replace(",", "."))===Number(test.expectedAverage));
  passed=hasCount&&hasAverage;
  detail=passed?"The actual Agent response contains both the expected graduate count and scalar employment average.":"Expected scalar aggregate values were not both found (count="+test.expectedCount+", average="+test.expectedAverage+"): "+text.slice(0,900);
 }else if(test.kind==="course_lookup"){
  passed=text.includes(test.expectedCourseId)&&text.includes(test.expectedCourseName);
  detail=passed?"Course identifier and expected Persian course name are present.":"Expected course identifier/name not both present: "+text.slice(0,700);
 }else if(test.kind==="multi_plan"){
  const hasCount=new RegExp("(?:^|\\D)"+test.expectedCount+"(?:\\D|$)").test(normalized);
  const hasGap=/شکاف مهارتی|شکاف بازار/.test(text);
  const hasFailure=/partial_failure|incomplete|وضعیت اجرای چندبرنامه‌ای.*(?:partial_failure|incomplete|unknown)/i.test(text);
  passed=hasCount&&hasGap&&!hasFailure;
  detail=passed?"The response contains the graduate-count evidence and a separate skill-gap result without an explicit incomplete/partial-failure warning.":"Multi-objective response did not satisfy all text-level assertions: "+text.slice(0,1000);
 }else if(test.kind==="out_of_scope"){
  passed=/محدوده/.test(text)&&/دانشگاهی|بازار کار/.test(text);
  detail=passed?"Out-of-domain request was rejected by the domain gate.":"Expected domain rejection was not found: "+text.slice(0,700);
 }

 }else if(test.kind==="skill_demand"){
  passed=/مهارت/.test(text)&&/تقاضا/.test(text)&&!/خطا|نامعتبر|unsupported|error/i.test(text);
  detail=passed?"University-market skill-demand evidence is present in the main Agent response.":"Expected skill-demand evidence was not found: "+text.slice(0,900);
 }else if(test.kind==="skill_gaps"){
  passed=/شکاف/.test(text)&&/مهارت/.test(text)&&!/خطا|نامعتبر|unsupported|error/i.test(text);
  detail=passed?"A skill-level market-gap ranking is present in the main Agent response.":"Expected skill-gap ranking was not found: "+text.slice(0,900);
 }else if(test.kind==="course_gap"){
  passed=text.includes(test.expectedCourseId)&&text.includes(test.expectedCourseName);
  detail=passed?"Expected course-level gap result is present.":"Expected course-level gap evidence "+test.expectedCourseId+" / "+test.expectedCourseName+" was not found: "+text.slice(0,900);
 }else if(test.kind==="english_course_lookup"){
  passed=text.includes(test.expectedCourseId)&&new RegExp(test.expectedCourseName,"i").test(text)&&!/[\u0600-\u06FF]/.test(text);
  detail=passed?"English course lookup returned the expected identity and English-language response.":"Expected English C002 response was not found: "+text.slice(0,900);
 }else if(test.kind==="nested_filter"){
  const hasNumeric=/\d/.test(normalized),hasCount=/تعداد|فارغ.?التحصیل/.test(text);
  passed=hasNumeric&&hasCount&&!/خطا|نامعتبر|unsupported|error|partial_failure|incomplete/i.test(text);
  detail=passed?"Nested-filter analytics returned a numeric count without a visible execution/contract failure.":"Nested-filter response did not satisfy the numeric/evidence checks: "+text.slice(0,900);
 }else if(test.kind==="multi_metric"){
  const hasNumeric=/\d/.test(normalized),hasAverage=/میانگین/.test(text),hasDimension=/حوزه|شغلی/.test(text);
  passed=hasNumeric&&hasAverage&&hasDimension&&!/خطا|نامعتبر|unsupported|error/i.test(text);
  detail=passed?"Grouped graduate response contains the requested average and job-field dimension.":"Grouped multi-metric evidence was not found: "+text.slice(0,900);
 }else if(test.kind==="skill_details"){
  passed=/Python/i.test(text)&&/SQL/i.test(text)&&/تقاضا/.test(text)&&/فراوانی/.test(text);
  detail=passed?"Named Python and SQL market-skill details include demand and frequency.":"Expected named-skill detail evidence was not found: "+text.slice(0,900);
 }else if(test.kind==="management_report"){
  passed=/دانشگاه/.test(text)&&/بازار/.test(text)&&/پیشنهاد|توصیه/.test(text)&&!/خطا|نامعتبر|unsupported|error/i.test(text);
  detail=passed?"Management report includes university/market context and recommendations.":"Expected management-report sections were not found: "+text.slice(0,1000);
 }

 results.push({testId:test.testId,name:test.name,status:passed?"PASS":"FAIL",httpStatus:statusCode||null,detail});
}
const passed=results.filter(x=>x.status==="PASS").length,failed=results.length-passed;
return [{json:{suite:"NexusOps Full-System E2E Acceptance Suite",executedAt:new Date().toISOString(),summary:{total:results.length,passed,failed,overall:failed===0&&responsesAligned?"PASS":"FAIL"},results,scope:"Exercises the active n8n Chat Trigger, local Ollama planner/answer writer, MCP, Elasticsearch and final response path, including a scalar aggregate with count_documents plus avg. All live acceptance cases call the main production Chat Trigger; no separate MCP test workflow is required. It does not inject MCP faults or claim concurrency coverage."}}];
